"item_function":"◆它可以烹饪普通料理和大厨专属料理，没有使用限制，任何人都可以使用。<br>◆烹饪时间为普通锅的60%。<br>【停止烹饪】<br>◆当红晶锅开始烹饪后，玩家可以使用浇水壶将其扑灭停止烹饪。<br>◆停止烹饪不会造成食材损失，但烹饪进度不会被保留，下次再次开始烹饪还是从头开始。<br>【整组烹饪】<br>◆当玩家同时佩戴{主厨勋章}和{时空勋章}，或通过{本源勋章}佩戴{主厨勋章}时，将解锁红晶锅的整组烹饪功能。<br>◆玩家可将食材堆叠放入红晶锅中，烹饪时将按食材堆叠数量最少的那个格子为准烹饪对应数量的料理，单次最多只能烹饪40个料理<br>◆牛奶帽(不可堆叠)、彩虹糖豆(一次性烹饪多个)等特殊料理的单次烹饪消耗的食材数量也会随最终可烹饪的数量减少，多余的食材将直接返还到玩家身上。<br>◆烹饪时间=(80-烹饪数量)/80*单个料理烹饪时长*烹饪数量*60%，单次烹饪数量越多，平均每个料理烹饪所需时长越短。<br>【本源增强】<br>◆当玩家通过本源勋章同时佩戴主厨勋章和时空勋章时，烹饪料理时间将再次减半(包括整组烹饪时间)。",
