"item_function":"◆佩戴时，玩家开矿效率×1.5倍，清理月雹效率×1.5倍(清理月雹和挖矿不是一个逻辑，所以不吃其他途径的开矿效率加成)。<br>◆佩戴时每开采完一座矿石会消耗一定的耐久，每次消耗的耐久会根据不同的矿石有所不同。<br>◆当耐久降到0点时，升级为{高级矿工勋章}。<br><tbs>开采目标<-->消耗耐久<th><br>月陨石、格罗姆雕像<->10点<td><br>盐矿、远古雕像、大理石雕像<->5点<td><br>大理石树-高<->3点<td><br>大理石树-中<->2点<td><br>大理石树-矮<->1点<td><br>石化树<->2点<td><br>石果<->0点<td><br>月雹<->2点<td><br>其他矿石<->1点<tbe><br>【搭配效果】<br>◆开矿效率可和大理石镐等工具叠加。<br>◆佩戴时能缓解{大理石镐}带来的副作用，饱食下降速度*1.5，移速*1。",
