"item_code":"medal_farm_plow_item",
"item_img":"",
"item_type":"C|M",
"update_version":"1.6.08.0",
"item_function":"◆可在耕地地皮上直接耕出3*3的整齐的土堆，如果要耕出土堆的位置有种植好的作物或者其他不可拾取的杂物则会跳过那个位置。<br>◆有18+9格容器，只能装种子，左侧18格为种子存储区，右侧9格为播种区，耕地时会按照播种区内的种子排布方式进行自动播种。<br>◆存放在高效耕地机中的种子保鲜时长翻倍。<br>◆可点击容器播种区下方的一键分配按钮对播种区内的种子进行快速分配，具体分配规则请参考扩展栏。<br>◆对着蚁狮造成的地陷使用可将其抹平。<br>◆耐久为0时失去工作能力，可使用燧石进行打磨恢复耐久。<br>【不朽之力】<br>◆可以对它使用{不朽宝石}给它赋予不朽之力，不朽后可继续使用不朽宝石提升不朽等级，最高可升至2级。<br>【空间之力】<br>◆可使用{时空宝石}对其进行弹性空间升级，升级后可使容器内格子堆叠无上限。<br>◆升级时还需额外消耗27颗{时空灵石}。<br>◆超出堆叠上限的道具单次只可取出1组，不可一次性全部取出。",
"easy_function":"",
