"item_function":"◆可在陆地上抽水，使用前需要先用水壶往里面加水排出里面的空气。<br>◆抽水时，会持续向四周发射水球(单次最多发射3颗)，作用范围和灭火器相同。<br>◆水球可灌溉耕地、可给水壶装水、可给{蓝晶制冰机}加水、可灭火。<br>◆发射的水球不会扑灭篝火、火坑。<br>◆抽水后五分钟内再次使用不需要重新加水，超过五分钟或者重载游戏后，则需要加水才能再次使用。<br>【潮湿】<br>◆当深井泵处于潮湿状态时，不需要加水就能直接抽水。<br>◆可以使用5颗{落水弹}对其进行改造，让它永久处于潮湿状态。",
