"item_img":"",
"item_type":"C",
"update_version":"1.6.08.0",
"item_function":"【答题】<br>◆佩戴时右击蒙昧勋章可打开一个答题面板，答题面板上会随机显示一道选择题，玩家选择正确的答案可以降低耐久，答错无影响。<br>◆题目默认为乱码，答题时玩家需手持{新华字典}才能解除乱码，乱码时瞎蒙是无法答对题的。<br>◆若已解除乱码，则答题时不需要再用新华字典进行解码，直到答对题目后才会变回乱码状态。<br>◆原本无阅读能力的角色，答对一题扣5点耐久。<br>◆原本有阅读能力的角色，答对一题扣10点耐久。<br>◆小鱼妹(沃特)算原本无阅读能力的角色，因为她只能把书当画册看，恒子戏称其为愣读。<br>【学习】<br>◆佩戴蒙昧勋章时，玩家手持新华字典并阅读{无字天书}进行学习，也可以降低蒙昧勋章耐久。<br>◆原本无阅读能力的角色，阅读一次扣8点耐久。<br>◆原本有阅读能力的角色，阅读一次扣16点耐久。<br>【升级】<br>◆耐久降为0后蒙昧勋章将升级为{智慧勋章}。",
