"item_code":"mandrakeberry",
"item_img":"",
"item_type":"D",
"update_version":"1.6.07.0",
"item_function":"◆曼德拉草的果实，直接食用加9.4饱食度，减5点精神、1点血量，并有致幻效果，吃完会使玩家处于迷迷糊糊的状态一小会儿，吃多了会直接睡着。<br>◆若玩家食用了过量曼德拉果后无法正常昏睡，则会额外扣除2点血和10点san值。<br>◆若玩家身上有蘑菇蛋糕带来的睡眠免疫效果，食用后可优先解除睡眠免疫。<br>◆可作为弹弓弹药使用，射中目标后可使目标昏睡(效果与催眠吹箭类似)。<br>【掉落】<br><tbs>消耗途径<-->{曼德拉种子}概率<-->{杂草种子}概率<th><br>玩家食用<->5%<->25%<td><br>喂鸟<->0<->12.5%<td><br>非玩家食用<->2%<->5%<td><br>作为弹药消耗<->2%<->5%<tbe><br>【本源增强】<br>{童心勋章}放入{本源勋章}并佩戴后，作为弹药击中目标后将额外获得以下增益：<br>◆催眠效果增强，催眠效率翻倍。",
"easy_function":"◆曼德拉草的果实，直接食用加9.4饱食度，减5点精神、1点血量，并有致幻效果，吃完会使玩家处于迷迷糊糊的状态一小会儿，吃多了会直接睡着。<br>◆若玩家食用了过量曼德拉果后无法正常昏睡，则会额外扣除2点血和10点san值。<br>◆若玩家身上有蘑菇蛋糕带来的睡眠免疫效果，食用后可优先解除睡眠免疫。<br>◆可作为弹弓弹药使用，射中目标后可使目标昏睡(效果与催眠吹箭类似)。<br>【掉落】<br><tbs>消耗途径<-->{曼德拉种子}概率<-->{杂草种子}概率<th><br>玩家食用<->10%<->50%<td><br>喂鸟<->0<->25%<td><br>非玩家食用<->4%<->10%<td><br>作为弹药消耗<->4%<->10%<tbe><br>【本源增强】<br>{童心勋章}放入{本源勋章}并佩戴后，作为弹药击中目标后将额外获得以下增益：<br>◆催眠效果增强，催眠效率翻倍。",
