"item_function":"◆佩戴时可以直接在地面种植农作物种子，不会受到植物的主动伤害(诸如海草、食人花、刺针旋花等)。<br>◆可以解锁制作沃姆伍德专属道具（活木除外），可制作{活木树苗}，可复活{树根宝箱}。<br>◆佩戴时不会被潮湿度影响san值。<br>◆曼德拉草跟随佩戴了虫木勋章的玩家时，不会发出咿咿呀呀的声音。<br>◆解锁肥料包新配方：鸟粪*4+腐烂物*2+硝石*1。<br>【肥力】<br>◆初始无肥力，肥力上限20点。<br>◆可使用肥料包或{秘制酱料}对其施肥，一个肥料包可提供20点肥力，一个秘制酱料可提供10点肥力。<br>◆鼠标移上去可查看当前肥力和作物收集进度。<br>【抚摸】<br>◆当肥力大于0时，玩家可以对其进行抚摸操作，抚摸后将消耗1点肥力，并在玩家脚下长出一朵小花。<br>◆若抚摸时有跟随着抚摸者的曼德拉草，则会安抚曼德拉草的情绪使它们重新种回土里。<br>◆抚摸后将获得持续4分钟的照料效果，每秒会对周围20范围内的作物进行一次照料。<br>【升级】<br>◆佩戴时每收获一种新的巨型作物，就会掉1点耐久，耐久掉完后将升级成{植物勋章}。",
