"item_function":"◆月光药水的上位替代品，对部分特定目标使用时可使其发生变异。<br>【外观变异】<br>◆对目标左键施法可使目标外观发生变异，例如可改变花、蕨类盆栽等物品的外观。<br>◆进行外观变异需要消耗2点耐久，对同一目标进行外观变异后的5秒内再次改变其外观不需要消耗耐久。<br>【品种变异】<br>◆对目标右键施法可使目标品种发生改变，例如可将草变为草蜥蜴、将树苗变成多枝树等。<br>◆进行品种变异需要消耗5点耐久，对同一目标进行品种变异后的5秒内再次改变其品种不需要消耗耐久。<br>【巨型果实变异】<br>◆对有对应植物接穗的巨型果实右键使用，有概率使其变成对应的{植物接穗}，变异失败则会使其直接炸开掉落果实及种子。<br>◆巨型果实变异需消耗20点耐久。",
