"item_img":"",
"item_type":"D",
"update_version":"1.6.08.0",
"item_function":"◆可饮用，饱食度+10，血量+10，精神值+100，并获得一个持续3分钟的月光Buff。<br>◆月光Buff存在期间玩家身上会散发月光，并且可以通过这个月光激活月光工具。<br>【能力清洗】<br>◆可使用瓶装月光清洗部分勋章的能力，清洗后变成{空白勋章}。<br>◆可使用瓶装月光清洗部分书籍的能力，清洗后变成{传承书页}。<br>◆可使用瓶装月光清洗超时空树根宝箱，解除它的时空锚点。<br>【注入月光】<br>◆佩戴{时空勋章}时，可用瓶装月光对唤星者魔杖注入月光，使其升级为唤月者法杖。<br>【返还】<br>◆饮用或清洗消耗掉瓶装月光后，有50%的概率返还一个空瓶子，否则会破碎成一个月光玻璃碎片。",
