"item_type":"B|Q",
"update_version":"1.6.06.0",
"item_function":"◆佩戴时可以解锁女武神专属装备的配方。<br>【女武神之力】<br>◆可将各种BOSS掉落的雕像图纸塞给它增加女武神之力，每消耗一张图纸可增加1点女武神之力，可重复塞相同的图纸。<br>◆女武神之力初始为0，上限为10。<br>◆若女武神之力大于0点，佩戴时还可获得额外的减伤，女武神之力越高减伤越高；若玩家原本就有减伤，则额外获得的减伤减半。<br>◆减伤比例=(25%*女武神之力/10)。<br>◆佩戴时击杀目标生物可获得精神和血量回复，女武神之力越高回复量越多；女武神回复量减半。<br>◆精神、血量回复量=(目标攻击*20%*女武神之力/10)；<br><tbs>女武神之力<-->减伤<-->回复量<th><br>0<->0%<->0<td><br>2<->5%<->目标攻击*4%<td><br>4<->10%<->目标攻击*8%<td><br>6<->15%<->目标攻击*12%<td><br>8<->20%<->目标攻击*16%<td><br>10<->25%<->目标攻击*20%<tbe><br>【攻击加成】<br>◆佩戴时，可对玩家的攻击进行加成，手持不同装备将受到不同程度的加成。<br>【本源增强】<br>◆放入{本源勋章}后击力加成倍数提升。<br><tbs>武器<-->攻击加成<-->本源加成<th><br>战斗长矛<->1.4倍<->1.8倍<td><br>警钟<->无<->1.1倍<td><br>其他<->1.1倍<->1.25倍<tbe>",
