"item_type":"F",
"update_version":"1.6.08.0",
"item_function":"◆初始血量300，初始伤害50，对玩家伤害倍率为1。<br>【属性提升】<br>◆复仇坎普斯的属性会随着玩家召唤的次数增加而缓慢提升。<br>◆血量=300+召唤次数*2，最高不超过750<br>◆伤害=50+向下取整(召唤次数/5)*1，最高不超过100<br>◆减伤=向下取整(召唤次数/10)*0.005，最高不超过0.25<br>【额外掉落】<br>◆复仇坎普斯死亡时，有概率额外掉落{坎普斯之灵}，掉落概率会随着召唤次数增加而提升。<br>◆掉落概率=召唤次数/225*0.2+0.05，最高不超过25%。概率区间：5%~25%。",
