"update_version":"1.6.06.0",
"item_function":"◆需佩戴{智慧勋章}且智慧值足够时才可阅读，需消耗20点智慧值。<br>◆阅读后san值-50，沃特愣读后san值+33，可以在附近召唤出一棵或多棵植物，只能在陆地上进行召唤。<br>◆阅读前可在地上放置一些特殊祭品用于献祭，献祭会影响不同植物的召唤概率，献祭详情可查阅扩展内容。<br>【特殊效果】<br>◆{虫木花}变异：在虫木花附近阅读并献祭{本源精华}，即可有概率使虫木花变异成{本源小树}，每献祭1个本源精华可增加25%概率，4个即可100%触发。<br>◆催长本源小树：阅读时若周围有矮小、中等阶段的本源小树，则可以使其直接进入下一阶段；若为施肥状态，则可立即吸收养分。<br>◆复活曼德拉草：阅读时若周围有已死亡的曼德拉草，则会优先去复活曼德拉草，单次最多复活10棵曼德拉草(不可堆叠)。<br>◆催熟嫁接树：阅读后催熟周围的嫁接树，单次最多可催熟30棵，不朽果树15棵。<br>◆催熟巨大作物：阅读后催熟周围农作物，使其无视条件直接成长为巨大作物，单次最多可催熟16棵，{不朽果实}8棵。<br>◆阅读时将优先触发上述特殊效果，一次性只能触发其中一种效果，触发后将不触发召唤功能。",
