"item_type":"F|Q",
"update_version":"1.6.06.0",
"item_function":"◆佩戴时可以在水面上行走，在水面跑动时耐久下降速度为正常速度，否则耐久下降速度为原来的5倍。<br>◆装备踏水勋章在水上攻击其他生物时，若目标生物血量不低于500点，则每次攻击都会额外扣除耐久。<br>◆目标血量越高消耗的耐久越多，单次攻击最多消耗4%耐久。<br>◆耐久为0时不消失，佩戴时仍然有踏水效果，但会以每秒1点的速度扣除玩家血量，每扣5次血，每秒扣血量+1。<br>【本源增强】<br>通过{本源勋章}佩戴时将额外获得以下增益：<br>◆佩戴时只要在水面上，耐久下降速度即为正常速度。<br>◆佩戴时可在洞穴虚空行走。<br>◆佩戴时在水面上攻击其他生物时不再额外扣除耐久。",
