"item_function":"◆佩戴时可以制作薇洛的专属道具，不怕火焰伤害，但是还是会过热。<br>◆精神过低时能够让周围的一只伯尼熊巨大化。<br>◆能掌握快速烹饪的技巧，可以用打火机烤食物。<br>◆给火堆添加燃料时有更高的效率~<br>◆可解锁一条专属配方：4个玻璃碎片合成一个空瓶子。<br>【本源增强】<br>通过{本源勋章}佩戴时将额外获得以下增益：<br>◆佩戴时若穿了{红晶甲}，则红晶甲的反伤伤害和红晶标记造成的灼烧伤害将提高至150%。<br>◆佩戴时若穿了{蓝晶甲}，则蓝晶甲的易伤伤害倍率提升至200%。<br>◆佩戴时若穿了{时空晶甲}，则可同时获得上述两条加成。",
