"item_function":"◆非常结实的护甲，穿戴时能帮助抵挡85%的伤害。<br>◆穿戴时玩家将不再受到火焰伤害(但依然会过热)。<br>【特殊效果】<br>◆穿戴蓝晶甲时攻击目标可获得充能，充能期间攻击目标或受到目标攻击时均有概率给目标添加蓝晶标记，使其减速、冰冻、易伤。<br>◆详细介绍请看扩展内容。<br>【不朽之力】<br>◆可使用{不朽宝石}给蓝晶甲赋予不朽之力，并且可继续使用不朽宝石提升不朽等级，最高可升至5级。<br>◆不朽蓝晶甲耐久为0时不会消失，仍可穿戴，但会失去防护效果。<br>◆不朽等级越高，蓝晶甲的减伤比例越高、耐久上限越高，不朽果实可补充的耐久越多。<br>◆不朽蓝晶甲具有混沌防御，不朽等级越高，混沌防御越高。<br>◆拥有不朽之力后，触发蓝晶标记效果将变成范围标记，可给范围3内的敌对目标均添加1层蓝晶标记，若可添加蓝晶标记的目标不超过1，则本次标记不消耗蓝晶充能。<br>◆给目标添加蓝晶标记的概率会受到不朽等级加成，不朽等级越高，触发概率越大。<br>◆单次给目标添加标记的层数也会随不朽等级提升而提升。<br><tbs>不朽等级<-->减伤比例<-->耐久上限<-->混沌防御<-->不朽果实可补充耐久<-->蓝晶标记概率<-->单次标记层数<th><br>0级<->85%<->945<->0<->不可补充<->max(充能层数-5,0)*0.05<->1<td><br>1级<->87%<->1155<->5<->420<->充能层数*0.05<->1<td><br>2级<->89%<->1365<->10<->472.5<->充能层数*0.075<->1<td><br>3级<->91%<->1575<->15<->525<->充能层数*0.1<->2<td><br>4级<->93%<->1785<->20<->577.5<->充能层数*0.125<->2<td><br>5级<->95%<->1995<->25<->630<->充能层数*0.15<->3<tbe>",
