"item_function":"◆佩戴时，附近有生物死亡会掉落灵魂，灵魂会自动吸附到玩家身上。<br>◆当玩家身上的灵魂数量达到最大时(所有角色均为20个)，或者物品栏没有容纳灵魂的空位时，超出的灵魂会被该勋章吸收，每吸收一个灵魂增加一点耐久。<br>◆当该勋章的耐久满了之后，额外吸附的灵魂会被虚空吞噬掉，沃拓克斯额外吸附的灵魂则会自动掉落为周围玩家治疗。<br>◆佩戴时将鼠标放在勋章上可直接右键消耗1点耐久释放1个灵魂用于治疗。<br>【灵魂跳跃】<br>◆佩戴时，若耐久不为0或物品栏有灵魂，可右键点击目标位置进行灵魂跳跃。<br>◆灵魂跳跃后，勋章将进入一个持续5秒的灵魂回响状态，灵魂回响期间不会立即消耗灵魂或耐久。<br>◆玩家在灵魂回响期间再次进行灵魂跳跃，或者灵魂回响状态结束后，才会消耗1个灵魂或者1点耐久。<br>◆若角色本身有灵魂跳跃能力，则优先触发角色本身的灵魂消耗逻辑，不满足消耗条件才消耗勋章耐久。",
