"item_function":"◆佩戴时使用陆钓鱼竿钓鱼能让鱼上钩的时间缩短为原来的40%。<br>◆钓到{遗失塑料袋}的概率为原来的1.5倍，消耗鱼饵的概率为原来的80%。<br>◆可以快速宰杀鱼类。<br>【耐久消耗】<br>◆佩戴时每钓到一种未记录的海鱼(包括龙虾)可消耗一定的耐久，并将其记录在勋章上。<br>◆若是使用海钓竿钓到的，则会消耗更多的耐久。<br>◆当耐久降到0点时，垂钓勋章会升级为{渔翁勋章}。<br><tbs>上钩目标<-->陆钓消耗<-->海钓消耗<th><br>时令鱼<->20点<->30点<td><br>花锦鲤、金锦鲤<->5点<->10点<td><br>龙虾、月光龙虾<->1点<->2点<td><br>甜味鱼、口水鱼<->3点<->6点<td><br>其他海鱼<->2点<->4点<tbe>",
