"item_function":"◆一个和所有水域连通的陆钓钓鱼池，可以使用陆钓钓竿在这个洞里钓到海鱼、龙虾、淡水鱼、鳗鱼 、熔岩鳗鱼、塑料袋。<br>◆玩家使用{玻璃钓竿}且装配任意食饵时，可有5%概率在虚空钓鱼池内钓出任何季节的时令鱼，佩戴{垂钓勋章}概率提升至7.5%，佩戴{渔翁勋章}概率提升至10%。<br>◆玩家使用玻璃钓竿且装配任意拟饵时，可有概率钓出{遗失塑料袋}，具体产出请看扩展内容。<br>◆虚空钓鱼池仅存在16分钟，16分钟后直接消失。<br>◆初始有20条鱼，最大容鱼量为20条，当鱼被钓完时会提前消失。<br>◆鱼被钓走后不可自然再生，只能使用{特制鱼食}来吸引更多的鱼。",
