"item_function":"◆是一把陆钓钓竿，可以在岩浆池中钓鱼。<br>◆可使鱼上钩时间减少2秒。<br>◆比起普通钓竿更不容易被鱼拖走。<br>◆有一格鱼饵栏，可以放入鱼饵，鱼饵可堆叠。<br>◆当玩家使用玻璃钓竿在不同水域钓鱼，且装有适配该水域的鱼饵时，可有概率钓到{遗失塑料袋}，钓到遗失塑料袋时有概率消耗掉鱼饵。<br>【不朽之力】<br>◆可使用{不朽宝石}给其赋予不朽之力(不需要消耗{不朽精华})。<br>◆当拥有不朽之力后，耐久上限变为原来的2倍。",
