"item_type":"I|Q",
"update_version":"1.6.06.0",
"item_function":"◆佩戴时可制作、使用弹弓和弹药，可制作便携式帐篷，可在篝火旁讲故事。<br>◆可解锁弹药匣以及勋章专属弹药的制作。<br>◆使用弹弓射击的速度会变快，前摇时间会被缩短，对普通射击和特殊射击均有加成(沃尔特的右键射击，下文均称作特殊射击)。<br>◆普通射击的前摇帧数-1，前摇帧数最高不超过10帧，最低不会低于5帧(除非玩家当前的前摇帧本来就低于5帧)。<br>◆特殊射击的前摇帧数-2，前摇帧数最高不超过12帧，最低不会低于5帧(除非玩家当前的前摇帧本来就低于5帧)。<br>◆佩戴时使用弹弓射击具有锁敌功能，在一定范围内优先攻击锁定的目标，直到目标失效或超出锁定范围(默认锁敌范围4.5格地皮)。<br>◆可以使用鼠标主动切换攻击目标，也可在内置设置面板关闭该功能，或调整锁定范围。<br>【本源增强】<br>通过{本源勋章}佩戴时将额外获得以下增益：<br>◆佩戴时使用童心箱换取礼物时，获得的弹药数量增加20%。<br>◆使用勋章专属弹药击中目标可受到额外增益(具体看对应弹药介绍)。<br>◆减少射击前摇帧数，普通射击前摇帧数最高不超过5帧，特殊射击前摇帧数最高不超过8帧。",
