"item_function":"◆来自混沌领域，是时空的主宰，本体是一块时空晶体，常年以猫形拟态出现。<br>◆血量27182，不能被任何手段攻击。<br>【时空迷雾】<br>◆时空吞噬者的四周会弥漫着时空迷雾，玩家处于时空迷雾中时，视野会变得很小，并降低移速。<br>◆玩家可通过佩戴{复眼勋章}、沙漠护目镜等道具来防护迷雾，缓解迷雾带来的负面效果。<br>◆时空迷雾中会不断地生成{时空虚影}、{时空乱流}、{时空晶矿}来干扰玩家的行动。<br>【饱食度】<br>◆饱食度上限27182，初始饱食度为0，可通过喂食{时空灵石}或{时空零食}增加饱食度。<br>◆只有可以被时空吞噬者看到、攻击到的玩家才可以给它喂食，否则它将无视玩家的存在拒绝进食。<br>◆当饱食度喂满后，时空吞噬者会心满意足地离开这个世界，并留下一个{时空宝藏}。<br>◆时空吞噬者默认的饱食下降速度为0，但如果时空迷雾中的玩家数量超过1时，它的饱食度将会开始下降，玩家数量越多，饱食度下降得越快；<br>◆具体计算公式：饥饿速度(每秒下降量)=向上取整(根号(时空迷雾中出现过的玩家最大数量-1)*8)<br><tbs>人数<-->1<-->2<-->3<-->4<-->5<-->6<-->7<-->8<th><br>饥饿速度<->0<->8<->12<->14<->16<->18<->20<->22<tbe><br>◆玩家离开时空迷雾后并不能马上缓解它的饥饿速度，当它每释放一次全世界范围的时空塌陷时，饥饿速度下降6点。<br>【时空之刃】<br>◆时空吞噬者非常黏人，会召唤时空之塔将玩家困在自身附近，并不断地召唤时空之刃督促玩家喂它吃东西。<br><tbs>名称<-->普通伤害<-->对玩家伤害<-->混沌伤害<-->时之伤<-->击飞距离<th><br>小型时空之刃<->90<->45<->10<->50<->3<td><br>中型时空之刃<->130<->65<->20<->75<->6<td><br>大型时空之刃<->170<->85<->30<->100<->9<tbe><br>【时空塌陷】<br>◆时空吞噬者若2分钟内没吃到东西，就会对处于时空迷雾中离自己较远的玩家释放一次时空塌陷。<br>◆若一天(8分钟)未进食，则会对所有不在时空迷雾内的玩家(包括非本世界的玩家)释放一次时空塌陷。<br>◆当玩家踩到时空塌陷时，会立即被传送到时空吞噬者旁边，并获得30点时之伤。<br>【离开】<br>◆时空吞噬者一旦被召唤后，除非被喂饱，否则将不会主动离开这个世界。<br>◆若时空迷雾长时间无人造访，它将带着时空迷雾在这个世界的各个角落寻找玩家。<br>◆在时空迷雾中燃放{时空弹}可驱散时空迷雾并请时空吞噬者提前离开(不会留下时空宝藏)。<br>【额外奖励】<br>◆它会记录吃下的时空零食数量，在离开时会留下所吃零食数量的2/3的{零食包装袋}藏于时空宝藏中。<br>◆它在离开时还有概率在时空宝藏中额外放一个{尘蛾巢台}，喂食的零食数量占比越小，概率越大。<br>◆概率=1-喂食的时空零食数量*2333/27182<br>◆额外尘蛾巢台的概率是具有宿命的，无法通过回档来刷，但可以对时空吞噬者使用{预言水晶球}来预知喂食零食的数量上限。",
"easy_function":"◆来自混沌领域，是时空的主宰，本体是一块时空晶体，常年以猫形拟态出现。<br>◆血量27182，不能被任何手段攻击。<br>【时空迷雾】<br>◆时空吞噬者的四周会弥漫着时空迷雾，玩家处于时空迷雾中时，视野会变得很小，并降低移速。<br>◆玩家可通过佩戴{复眼勋章}、沙漠护目镜等道具来防护迷雾，缓解迷雾带来的负面效果。<br>◆时空迷雾中会不断地生成{时空虚影}、{时空乱流}、{时空晶矿}来干扰玩家的行动。<br>【饱食度】<br>◆饱食度上限27182，初始饱食度为0，可通过喂食{时空灵石}或{时空零食}增加饱食度。<br>◆只有可以被时空吞噬者看到、攻击到的玩家才可以给它喂食，否则它将无视玩家的存在拒绝进食。<br>◆当饱食度喂满后，时空吞噬者会心满意足地离开这个世界，并留下一个{时空宝藏}。<br>◆时空吞噬者默认的饱食下降速度为0，但如果时空迷雾中的玩家数量超过1时，它的饱食度将会开始下降，玩家数量越多，饱食度下降得越快；<br>◆具体计算公式：饥饿速度(每秒下降量)=向上取整(根号(时空迷雾中出现过的玩家最大数量-1)*8)<br><tbs>人数<-->1<-->2<-->3<-->4<-->5<-->6<-->7<-->8<th><br>饥饿速度<->0<->8<->12<->14<->16<->18<->20<->22<tbe><br>◆玩家离开时空迷雾后并不能马上缓解它的饥饿速度，当它每释放一次全世界范围的时空塌陷时，饥饿速度下降6点。<br>【时空之刃】<br>◆时空吞噬者非常黏人，会召唤时空之塔将玩家困在自身附近，并不断地召唤时空之刃督促玩家喂它吃东西。<br><tbs>名称<-->普通伤害<-->混沌伤害<-->时之伤<-->击飞距离<th><br>小型时空之刃<->90<->10<->30<->3<td><br>中型时空之刃<->130<->20<->40<->6<td><br>大型时空之刃<->170<->30<->50<->9<tbe><br>【时空塌陷】<br>◆时空吞噬者若2分钟内没吃到东西，就会对处于时空迷雾中离自己较远的玩家释放一次时空塌陷。<br>◆若一天(8分钟)未进食，则会对所有不在时空迷雾内的玩家(包括非本世界的玩家)释放一次时空塌陷。<br>◆当玩家踩到时空塌陷时，会立即被传送到时空吞噬者旁边，并获得15点时之伤。<br>【离开】<br>◆时空吞噬者一旦被召唤后，除非被喂饱，否则将不会主动离开这个世界。<br>◆若时空迷雾长时间无人造访，它将带着时空迷雾在这个世界的各个角落寻找玩家。<br>◆在时空迷雾中燃放{时空弹}可驱散时空迷雾并请时空吞噬者提前离开(不会留下时空宝藏)。<br>【额外奖励】<br>◆它会记录吃下的时空零食数量，在离开时会留下所吃零食数量的2/3的{零食包装袋}藏于时空宝藏中。<br>◆它在离开时还有概率在时空宝藏中额外放一个{尘蛾巢台}，喂食的零食数量占比越小，概率越大。<br>◆概率=1-喂食的时空零食数量*4333/27182<br>◆额外尘蛾巢台的概率是具有宿命的，无法通过回档来刷，但可以对时空吞噬者使用{预言水晶球}来预知喂食零食的数量上限。",
