"item_function":"◆只存在于时空迷雾中，时空乱流会以一定的规律进行周期性的能量释放，会对范围内的生物造成20点电击伤害+10点混沌伤害+30点时之伤。<br>◆玩家使用绝缘道具时，可抵御一半的电击伤害。<br>◆可以使用捕虫网捕捉，捕捉次数为5(即效率为1的捕虫网需要捕捉5次)，每次捕捉的成功概率为(1-(剩余捕捉次数-捕捉效率)/5)<br><tbs>剩余捕捉次数<-->5<-->4<-->3<-->2<-->1<th><br>捕虫网成功率<->20%<->40%<->60%<->80%<->100%<td><br>{月光玻璃网}成功率<->100%<->100%<->100%<->100%<->100%<tbe><br>◆捕捉成功可获得1~2颗{时空灵石}，捕捉失败则会受到一次乱流攻击。",
