"item_function":"◆9格容器，不可燃，可破坏，可作为普通箱子使用。<br>【换取礼物】<br>◆当9个格子铺满指定道具并且无堆叠时，可点击下方的换取礼物按钮，将道具分享给{时空吞噬者}，它收到礼物后宝箱将消失并留下谢礼。<br><tbs>指定道具<-->谢礼<th><br>{时空零食}*9<->{时空碎片}*9+{零食包装袋}*9+时空宝箱{皮肤券}*1<td><br>{红晶甲}*1+{蓝晶甲}*1+{时空宝石}*1+时空零食*6<->{时空晶甲}*1+时空碎片*6+零食包装袋*6+时空宝箱皮肤券*1<tbe>",
