"item_type":"L|M",
"update_version":"1.6.08.0",
"item_function":"◆具有预知未来的能力，对部分有宿命的目标使用可预测它的未来。<br>◆可对具有宿命的书籍使用，使用后可直接看到阅读后的结果；若书籍支持献祭，则预言结果会根据当前献祭范围内祭品数量而发生对应变化，每次预言消耗2点耐久。<br>◆可对巨型不朽果实使用，使用后可查看对其使用月光药水后的结果，每次预言消耗2点耐久。<br>◆可对任意藏宝图使用，使用后会在地图上用红色叉叉标出藏宝图点位置，标记仅存在60秒，每次预言宝藏位置消耗10点耐久。<br>【搭配效果】<br>◆佩戴{时空勋章}时可对奉纳盒使用，使用后可直接获得宝石解谜的答案，每次预言消耗10点耐久。<br>◆佩戴时空勋章时可对时空吞噬者使用，使用后可以知道本次召唤的时空吞噬者在保证能额外出{尘蛾巢台}的前提下，可喂食{时空零食}的数量上限，每次预言消耗50点耐久。<br>◆佩戴时空勋章时右键水晶球自己可消耗10点耐久进行预言，可获得持续5分钟的预知Buff，效果期间玩家把鼠标移到书籍、巨型不朽果实上时可直接无消耗查看预言结果。<br><tbs>预言目标<-->耐久消耗<th><br>{巨型不朽果实}<->2<td><br>{未解之谜}<->2<td><br>{怪物图鉴}<->2<td><br>{植物图鉴}<->2<td><br>{不朽之谜}<->2<td><br>{藏宝图}<->10<td><br>{遗失藏宝图}<->10<td><br>{奉纳盒}<->10<td><br>{时空吞噬者}<->50<tbe>",
