"item_function":"◆携带在身上时，右键可打开传送列表，列表内会显示当前世界的其他玩家(包括已死亡玩家)和传送塔，点击选择目标后可传送至目标点附近，传送后消耗1枚时空符文。<br>◆可以对部分道具使用，使用后可以传送到相应的目标点附近，并消耗1枚时空符文。<br>◆若存在多个目标点，则会优先传送至距离玩家5格地皮外的目标点处。<br><tbs>道具名<-->传送目标点<-->备注<th><br>{藏宝图}<->对应的藏宝点附近<-><td><br>{遗失藏宝图}<->对应的藏宝点附近<-><td><br>瓶中信<->对应的沉底宝藏上方<->需要去过月亮碎片岛，且佩戴了{踏水勋章}<td><br>鹿角<->赃物袋<-><td><br>麋鹿茸<->赃物袋<-><td><br>食人花种子<->食人花<-><td><br>麋鹿鹅羽毛<->麋鹿鹅<-><td><br>亮茄外壳<->致命亮茄<-><td><br>废料<->被丢弃的垃圾<-><td><br>纯粹辉煌<->裂隙<-><td><br>纯粹恐惧<->噩梦猪人<-><tbe><br>【本源增强】<br>{时空勋章}放入{本源勋章}并佩戴后将额外获得以下效果：<br>◆快速挖宝：对藏宝图、遗失藏宝图使用时空符文，可在地上临时打开一个和宝藏连通的洞穴，直接拿到宝藏奖励。<br>◆沉底宝藏：对有宝藏的瓶中信使用时空符文，可直接在原地获取到沉底宝箱。",
