"item_function":"◆佩戴时移动速度*1.2。<br>◆可以使用强征传送塔进行自由传送，一个人即可完成空间穿越。<br>◆自由传送将消耗空间勋章的耐久，传送得越远消耗的耐久越多，单次传送最低消耗10点耐久，最多消耗40点耐久。<br>【绑定传送塔】<br>◆可将空间勋章和某个传送塔进行绑定(可变更绑定对象)。<br>◆绑定后，玩家在佩戴空间勋章时，可在任意地方直接右键空间勋章消耗20点耐久传送至绑定的传送塔处。",
