"item_type":"L|P|E|M",
"update_version":"1.6.08.0",
"item_function":"◆非常结实的护甲，穿戴时能帮助抵挡85%的伤害。<br>◆穿戴时玩家将不再受到火焰伤害(但依然会过热)。<br>◆同时拥有背包和护甲的功能，自带8格容器，被打爆时会掉落里面的所有物品。<br>◆若受到攻击后耐久小于等于20%，且自身格子内拥有可补充耐久的材料，则会自动消耗材料补充耐久。<br>◆可以抵御击飞效果，变成击退。<br>【特殊效果】<br>◆时空晶甲同时具备{红晶甲}、{蓝晶甲}的功能，穿戴时攻击目标可同时获得红晶充能、蓝晶充能。<br>◆红晶充能期间攻击目标有概率给目标添加红晶标记，对其造成灼烧伤害；受到目标攻击时将消耗所有充能对目标造成反伤。<br>◆蓝晶充能期间攻击目标或受到目标攻击时均有概率给目标添加蓝晶标记，使其减速、冰冻、易伤。<br>◆详细介绍请看扩展内容。<br>【空间之力】<br>◆可使用{时空宝石}对其进行弹性空间升级，升级后可使容器内格子堆叠无上限。<br>◆超出堆叠上限的道具单次只可取出1组，不可一次性全部取出。<br>【不朽之力】<br>◆可使用{不朽宝石}给时空晶甲赋予不朽之力(不需要消耗{不朽精华})，并且可继续使用不朽宝石提升不朽等级，最高可升至5级。<br>◆不朽时空晶甲耐久为0时不会消失(里面的物品也不再会全部掉落)，仍可穿戴，但会失去防护效果。<br>◆不朽等级越高，时空晶甲的减伤比例越高、耐久上限越高，不朽果实可补充的耐久越多。<br>◆随着不朽等级的提升，格子数量也会增加，每级增加2格，最高可增加到14格。<br>◆不朽时空晶甲具有混沌防御，不朽等级越高，混沌防御越高。<br>◆拥有不朽之力后，触发红、蓝晶标记效果将变成范围标记，可给范围3内的敌对目标均添加1层红、蓝晶标记，若可添加标记的目标不超过1，则本次标记不消耗充能。<br>◆给目标添加标记的概率会受到不朽等级加成，不朽等级越高，触发概率越大。<br>◆单次给目标添加标记的层数也会随不朽等级提升而提升。<br><tbs>不朽等级<-->格子数量<-->减伤比例<-->耐久上限<-->混沌防御<-->不朽果实可补充耐久<-->标记概率<-->单次标记层数<th><br>0级<->8格<->85%<->945<->0<->不可补充<->max(充能层数-5,0)*0.05<td><br>1级<->10格<->87%<->1155<->5<->420<->充能层数*0.05<->1<td><br>2级<->12格<->89%<->1365<->10<->472.5<->充能层数*0.075<->1<td><br>3级<->14格<->91%<->1575<->15<->525<->充能层数*0.1<->2<td><br>4级<->14格<->93%<->1785<->20<->577.5<->充能层数*0.125<->2<td><br>5级<->14格<->95%<->1995<->25<->630<->充能层数*0.15<->3<tbe>",
"easy_function":"",
"item_naijiu":"945HP<br><tbs>道具<-->补充耐久<-->不朽后<th><br>{红晶}<->315<->315<td><br>{蓝晶}<->315<->315<td><br>{时空灵石}<->315<->315<td><br>{不朽精华}<->0<->315<td><br>{不朽果实}<->0<->420<tbe>",
