"item_function":"◆购买、使用勋章特有皮肤的道具。<br>【皮肤币】<br>◆风花雪月的耐久即为皮肤币。<br>◆装备时右键风花雪月可打开皮肤购买面板，可消耗皮肤币购买解锁喜欢的皮肤。<br>◆对解锁过皮肤的物品使用可以更换其皮肤，每次更换需要消耗2个皮肤币。<br>◆更换目标皮肤后会有5秒冷却时间，冷却时间内对同一目标重复使用不会额外消耗皮肤币。<br>◆部分皮肤只能使用{皮肤券}才能解锁。<br>◆装备时对玩家自己施法则可以给风花雪月自身换皮肤。<br>【撒币】<br>◆装备风花雪月时可对目标进行远程攻击，攻击时将消耗10点耐久召唤一枚从天而降的血汗钱砸向目标，造成88点伤害(不受玩家buff加成)。<br>◆被血汗钱击中的目标将获得一个持续2分钟的萎靡buff，萎靡状态的目标伤害将降为原来的80%。",
