"item_function":"◆可直接食用，+9.4饱食度，+0.5生命。<br>◆可在火上烹饪，烹饪后变成烤种子。<br>【种植】<br>◆可种植出{包果}，压力值小于等于1则可变成{巨型包果}。<br>◆适合种植的季节为春夏秋冬，水分需求3级。<br>◆肥料配比：催长剂-8，堆肥-8，粪肥+16(图鉴上的一个箭头表示2点)。<br>◆需在相邻1格的地皮范围内同时存在9棵及以上的包果才能形成家族。<br>◆植株可燃，结出果实后不会腐烂，采摘后只能获得包果或巨型包果，不能获得包果种子。<br>◆生长周期为先急后缓型，[种子→萌芽]阶段较短，[萌芽→小→中]阶段非常短，[中→成熟]阶段非常长。<br>◆重量区间233.33~666.66。",
