"item_function":"◆使用后可在附近召唤随机一种暗影生物，拥有9000点血量。<br>◆召唤的暗影生物在脱离加载范围、重载游戏后就会消失。<br><tbs>怪物名<-->权重<th><br>爬行恐惧<->2<td><br>恐怖尖喙<->2<td><br>潜伏梦魇<->1<tbe><br>【掉落】<br>◆暗影生物初始有12点包果价值，玩家每被攻击到1次，降低1点包果价值。<br>◆暗影生物直接击杀不产生任何掉落物，当玩家佩戴{正义勋章}并且正义值足够时，击杀可额外掉落对应价值的奖励。<br>◆消耗的正义值=当前包果价值*2<br>【分裂】<br>◆每次使用暗影挑战符有20%的概率触发分裂。<br>◆召唤的暗影生物会分裂成4只3000血的同种类暗影生物，每只包果价值为4。<br>【回收】<br>◆可以将其塞给大帅鸽、咸鱼、猫猫雕像，换取1个{包果}。",
