"item_type":"O|P",
"update_version":"1.6.08.0",
"item_function":"◆来自混沌领域，具有混沌实体抵抗，不可燃烧、不可冰冻、不可催眠，血量16180。<br>【阶段】<br>◆当驱光遗骸的血量减少至一定量时，会进入不同的阶段，随着阶段的变化驱光遗骸的体型、机动性、技能丰富性都会有所提升。<br>◆阶段的改变不可逆（只会提升不会下降）。<br><tbs>阶段<-->触发血量比例<-->移速<-->攻击间隔<-->攻击范围<-->新增技能<th><br>1<->100%<->5<->2<->8<->瘴气孢子<td><br>2<->85%<->6<->1.5<->9<->虚空箭<td><br>3<->50%<->8<->1.5<->10<->嗜血箭、血色飓风<td><br>4<->25%<->10<->1<->12<->嗜血三连箭<tbe><br>【瘴气孢子】<br>◆向目标释放孢子并爆炸，可对目标造成60点基础伤害+15点混沌伤害，将会在爆炸位置生成瘴气。<br>◆从第2阶段开始，瘴气孢子爆炸后会额外生成2只绝望螨，移速=暗影尖啸者速度-1,爆炸伤害与瘴气孢子相同。<br>◆从第4阶段开始，每只绝望螨爆炸后会分裂成3只绝望螨(只会分裂一次)。<br>◆驱光遗骸死亡后，它所制造的瘴气也会随之消失。<br>【虚空箭】<br>◆高速射向目标的飞箭，可造成60点基础伤害+30点混沌伤害。<br>【嗜血箭】<br>◆伤害与虚空箭相同，射中目标后会原路返回至驱光遗骸处，为其提供回血。<br>◆嗜血箭回血量=向上取整((造成的伤害+5)*1.5^阶段数)<br>◆{黑暗血糖}可使嗜血箭的回血量减半。<br>【血色飓风】<br>◆向目标位置释放一个存在8秒的血红色龙卷风，每次击中可造成15点基础伤害+5点混沌伤害。<br>◆每次击中目标都会使目标掉落物品栏第一个物品，并将地上的物品卷飞。<br>【嗜血三连箭】<br>◆连续向目标发射三只嗜血箭，伤害、效果完全等同于嗜血箭。",
