"item_function":"◆由{虫木花}变异而成的一棵树，不可点燃。<br>◆总共有3个阶段，分别是矮小、中等、高大。<br><tbs>阶段<-->生长周期<-->砍伐次数<-->砍伐掉落<th><br>矮小<->20天<->5次<->木头*1<td><br>中等<->20天<->10次<->木头*2<td><br>高大<->(施肥+20天)*4<->15次<->木头*3<tbe><br>【开花】<br>◆在高大阶段时，玩家可使用{本源精华}进行施肥，施肥后花冠将会变色，20天后将会完全吸收养分并开出一朵花。<br>◆当开出3朵花后，再施一次肥并等待20天，即可成长为{本源之树}。<br>【催长】<br>◆在矮小、中等阶段时，玩家可使用本源精华对其施肥催长，也可以在其边上阅读{植物图鉴}催长，直接进入下一阶段。<br>◆在高大阶段并施肥变色后，可在其边上阅读植物图鉴加速养分吸收，直接开花。",
