"item_type":"Q",
"update_version":"1.6.08.0",
"item_function":"◆由本源小树生长而来的巨树，拥有比原生水中木更巨大的树冠和树荫，树荫半径36(9格地皮)。<br>◆砍伐50次可砍倒，砍倒可掉落20块木头。<br>◆单次砍伐效率最高不能超过20点。<br>【恒温】<br>◆本源之树的树荫下，温度恒定在35，且玩家进入本源之树范围时体温会立即变为35。<br>◆在树荫中的植物不会枯萎，且不会自燃。<br>【避雷】<br>◆本源之树具有避雷针效果，在其范围内的实体不会受到雷击。<br>【避茄】<br>◆亮茄虚影不会寄生本源之树树荫范围内的植物。<br>【避地陷】<br>◆玩家处于树荫中时，可保护玩家不受到蚁狮地陷的骚扰；<br>◆哪怕玩家已经收到地陷的预警了，进入树荫范围也可以马上摆脱蚁狮的愤怒。<br>【躲猫猫】<br>◆当玩家处于树荫中时，可保护玩家不受到时空吞噬者对所有不在时空迷雾内的玩家释放的时空塌陷的召唤。<br>◆若玩家已经被时空吞噬者盯上了再跑入树荫则无法受到保护。",
